/* ============================================================
   ENKRIPSI / DEKRIPSI (konten) — AES-GCM
   ============================================================ */
function b64u(r){var e="",a=32768;for(var l=0;l<r.length;l+=a){e+=String.fromCharCode.apply(null,Array.prototype.slice.call(r,l,l+a))}return btoa(e).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"")};
function b64d(e){e=e.replace(/-/g,"+").replace(/_/g,"/");while(e.length%4)e+="=";var r=atob(e);var a=new Uint8Array(r.length);for(var n=0;n<r.length;n++)a[n]=r.charCodeAt(n);return a};
function deriveKey(e){var r=new TextEncoder;var t=r.encode("hanhaoyu-kripto-v3-salt");var n=r.encode(String(e||"hanhaoyu"));return crypto.subtle.importKey("raw",n,"PBKDF2",false,["deriveKey"]).then((function(e){return crypto.subtle.deriveKey({name:"PBKDF2",salt:t,iterations:21e4,hash:"SHA-256"},e,{name:"AES-GCM",length:256},false,["encrypt","decrypt"])}))};
async function enkripsiTeks(e,n){var r=crypto.getRandomValues(new Uint8Array(12));var a=await deriveKey(e);var t=await crypto.subtle.encrypt({name:"AES-GCM",iv:r},a,(new TextEncoder).encode(String(n||"")));return"HHC3:"+b64u(r)+":"+b64u(new Uint8Array(t))};
async function dekripsiTeks(r,e){try{if(!e||String(e).indexOf("HHC3:")!==0)return null;var t=String(e).split(":");if(t.length!==3)return null;var n=b64d(t[1]);var i=b64d(t[2]);var a=await deriveKey(r);var d=await crypto.subtle.decrypt({name:"AES-GCM",iv:n},a,i);return(new TextDecoder).decode(d)}catch(r){return null}};
